INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (1, 'アコースティックギター', 'str01.jpg', '生音が響くため屋外やスタジオ等がおすすめ。エレキギターとは違い弦が硬いため、抑えるのには良い練習になります。', 500, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (2, 'アコースティックギター', 'str02.jpg', '生音が響くため屋外やスタジオ等がおすすめ。エレキギターとは違い弦が硬いため、抑えるのには良い練習になります。', 500, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (3, 'エレキギターレスポール', 'str03.jpg', '太く甘いサスティン長めが特徴。ロックなで重低音の曲を演奏におすすめ。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (4, 'エレキギターレスポール', 'str04.jpg', '太く甘いサスティン長めが特徴。ロックなで重低音の曲を演奏におすすめ。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (5, 'エレキギターストラトキャスター6弦', 'str05.jpg', 'クリアな音からレスポールのような重低音に近いまでの多彩な表現を可としています。演奏するジャンルが特に決まっていなければ、どのジャンルにも対応できるので初心者におすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (6, 'エレキギターストラトキャスター6弦', 'str06.jpg', 'クリアな音からレスポールのような重低音に近いまでの多彩な表現を可としています。演奏するジャンルが特に決まっていなければ、どのジャンルにも対応できるので初心者におすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 900, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (7, 'エレキギタージャズマスター6弦', 'str07.jpg', '太く甘い中低域豊かなトーンが生まれ、クリーン時は繊細で温かみがあり、歪ませるとジャキジャキとした高域の抜けが良いザクザクサウンドになります。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 900, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (8, 'エレキギタージャガー6弦', 'str08.jpg', 'シャープでブライトな高域強調のエッジーなトーンが特徴で、クリーン時はツゥワングとチムのような歯切れ良さ、歪み時はパンチーで直接的な響きが魅力です。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 900, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (9, 'エレキギターテレキャスター', 'str09.jpg', '鋭くパンチの効いたクリアでジャカジャカなサウンドが特徴です。一音一音が目立つため、目立つような演奏をするのにおすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (10, 'エレキギターテレキャスター', 'str10.jpg', '鋭くパンチの効いたクリアでジャカジャカなサウンドが特徴です。一音一音が目立つため、目立つような演奏をするのにおすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (11, 'エレクトリックアコースティックギター', 'str11.jpg', 'アコースティックギターにアンプ接続ができるようになり、いろんな音が楽しめます。紹介したとおり、アコースティックギターにもなるため、生音が響くため場所に注意してください。アンプの貸し出しもしています。', 700, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (12, 'エレクトリックアコースティックギター', 'str12.jpg', 'アコースティックギターにアンプ接続ができるようになり、いろんな音が楽しめます。紹介したとおり、アコースティックギターにもなるため、生音が響くため場所に注意してください。アンプの貸し出しもしています。', 700, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (13, 'セミアコースティックギター', 'str13.jpg', 'セミアコは「センターブロック」と呼ばれる木材が中に入っており、ハウリングに強くロックやブルースなど万能に対応します。サウンドホールがあるので多少は響くので練習場所には注意してください。アンプ貸出もしています。', 800, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (14, 'セミアコースティックギター', 'str14.jpg', 'セミアコは「センターブロック」と呼ばれる木材が中に入っており、ハウリングに強くロックやブルースなど万能に対応します。サウンドホールがあるので多少は響くので練習場所には注意してください。アンプ貸出もしています。', 800, 6, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (15, 'フルアコースティックギター', 'str15.jpg', 'フルアコは内部が完全に空洞で、温かみのある箱鳴り感が特徴、主にジャズで使用されます。 サウンドホールがあるので多少は響くので練習場所には注意してください。アンプ貸出もしています。', 800, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (16, 'フルアコースティックギター', 'str16.jpg', 'フルアコは内部が完全に空洞で、温かみのある箱鳴り感が特徴、主にジャズで使用されます。 サウンドホールがあるので多少は響くので練習場所には注意してください。アンプ貸出もしています。', 800, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (17, 'アコースティックベース4弦', 'str17.jpg', 'アコースティックギターのベースバージョンとなります。生音が響くため屋外やスタジオ等がおすすめ。エレキベースとは違い弦が硬いため、抑えるのには良い練習になります。', 500, 10, '右');
