INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (19, 'エレキベースジャズベース4弦', 'str21.jpg', 'シャープな音からプレベに近い低音を表現できます。また、どのジャンルにも対応できるので初心者におすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 10, '右');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (20, 'エレキベースジャズベース4弦', 'str22.jpg', 'シャープな音からプレベに近い低音を表現できます。また、どのジャンルにも対応できるので初心者におすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 700, 6, '左');
INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (21, 'エレキベースジャズベース5弦', 'str23.jpg', 'シャープな音からプレベに近い低音を表現できます。また、どのジャンルにも対応できるので初心者におすすめです。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。さらに低い弦を追加することで、ドロップチューニングも必要なくなるので、さらに多くのジャンルの曲の演奏が可能となります。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 900, 10, '右');
