INSERT IGNORE INTO string_instrument (id, name, image_name, description, price, capacity, handedness ) VALUES (23, 'エレキベースプレシジョンベース4弦', 'str25.jpg', '太く柔らかなサウンドやしっかりとした低音が出せるのが特徴。ロック、メタル、ポップスを演奏するのにおすすめ。アンプも貸出可のため、ヘッドホンをつけて自宅で練習もできます。', 800, 10, '右');
